// Intent Detection & Entity Extraction
const input = $json.body || $json;
const message = (input.message || input.title || '').trim();
const lower = message.toLowerCase();

let intent = input.intent || 'faq';
let category = input.category || 'general';

// 1. Detect Tracking Intent
const trackMatch = message.match(/CP-\d{4}-\d{4}/i);
if (trackMatch || lower.includes('status of') || lower.includes('track')) {
  intent = 'track';
  return {
    intent,
    trackingId: trackMatch ? trackMatch[0].toUpperCase() : 'CP-2026-1041',
    originalMessage: message
  };
}

// 2. Detect Complaint / Maintenance Intent
const complaintWords = ['broken', 'leak', 'water', 'not working', 'repair', 'issue', 'complaint', 'dirty', 'wifi down', 'tap', 'ac not', 'smell', 'light'];
if (complaintWords.some(w => lower.includes(w)) || lower.startsWith('complaint:')) {
  intent = 'complaint';
  if (lower.includes('water') || lower.includes('tap') || lower.includes('plumb')) category = 'maintenance';
  else if (lower.includes('wifi') || lower.includes('router') || lower.includes('internet')) category = 'it_network';
  else if (lower.includes('hostel') || lower.includes('room')) category = 'hostel';
  else category = 'maintenance';
}
// 3. Detect Suggestion Intent
else if (lower.includes('suggest') || lower.includes('recommend') || lower.includes('would be great if') || lower.includes('feedback')) {
  intent = 'suggestion';
  category = lower.includes('library') ? 'academics' : 'general';
}
// 4. Detect Event Proposal Intent
else if (lower.includes('event') || lower.includes('hackathon') || lower.includes('proposal') || lower.includes('workshop') || lower.includes('club')) {
  intent = 'event_proposal';
  category = 'student_activities';
}
// 5. Default: Grounded FAQ / Receptionist Query
else {
  intent = 'faq';
}

// Check missing details if complaint
const hasRoomSpecifics = /room\s*\d+|room\s*no|washroom\s*\d+|wing\s*[a-z]|floor\s*\d+/i.test(lower);
const needsVoiceClarification = intent === 'complaint' && !hasRoomSpecifics && (input.call_consent !== false);

return {
  intent,
  category,
  message,
  needsVoiceClarification,
  studentName: input.student_name || 'Student',
  studentEmail: input.student_email || 'student@hitam.org',
  studentPhone: input.student_phone || '+91 9876543210',
  location: input.location || (lower.includes('hostel') ? 'Hostel Block 3' : 'Campus Main Block'),
  urgency: lower.includes('urgent') || lower.includes('emergency') ? 'high' : 'medium',
  callConsent: input.call_consent !== false
};

// Dummy Operational Data for FAQ Route
const q = $json.message || 'Campus inquiry';
return {
  n8n_execution: 'completed',
  route_matched: 'faq',
  intent: 'receptionist_faq',
  query: q,
  answer: 'Hostel gate closes strictly at 6:30 PM for all residents. Outpass must be applied via the portal at least 6 hours in advance with parent consent. Biometric attendance recorded at 8:30 PM daily.',
  source: 'HITAM Student Handbook 2026',
  confidence: 'high',
  status: 'answered_instantly'
};

// Dummy Operational Data for Suggestion Route
const trackingId = 'CP-2026-' + Math.floor(1050 + Math.random() * 50);
return {
  n8n_execution: 'completed',
  route_matched: 'suggestion',
  tracking_id: trackingId,
  suggestion: $json.message || 'Request for additional laptop charging sockets in library',
  category: 'academics',
  assigned_department: 'Academic Affairs & Library Committee',
  reviewer: 'Dr. B. Surendra Reddy (Dean Academics)',
  status: 'assigned',
  estimated_time_of_solve: '24 - 48 hours',
  review_action: 'Placed on weekly academic committee agenda'
};

// Dummy Operational Data for Event Proposal Route
const trackingId = 'CP-2026-' + Math.floor(1060 + Math.random() * 50);
return {
  n8n_execution: 'completed',
  route_matched: 'event_proposal',
  tracking_id: trackingId,
  event_title: $json.message || 'HITAM 24hr AI Hackathon 2026',
  venue: 'Main Auditorium / Amphitheater',
  assigned_department: 'Student Activities & SSG',
  faculty_approver: 'Dr. Arvind S (Principal) & SSG Advisor',
  status: 'awaiting_approval',
  estimated_time_of_solve: '48 hours (Faculty Signoff)',
  budget_tier: 'Student Senate Sanctioned'
};

// Dummy Operational Data for Live Ticket Tracking
const tid = $json.trackingId || 'CP-2026-1041';
return {
  n8n_execution: 'completed',
  route_matched: 'track',
  tracking_id: tid,
  title: 'Hostel 3 plumbing maintenance',
  department: 'Facilities & Maintenance',
  status: 'in_progress',
  estimated_time_of_solve: '1 hour 45 minutes remaining',
  steps_completed: [
    { step: 'running_n8n', status: 'done', label: 'Running n8n Orchestrator' },
    { step: 'raising_request', status: 'done', label: 'Raising Request' },
    { step: 'request_raised', status: 'done', label: 'Request Raised: ' + tid },
    { step: 'in_progress', status: 'active', label: 'Crew Dispatched & Fixing' },
    { step: 'estimated_solve', status: 'pending', label: 'Estimated Solve: ~2 hrs' }
  ]
};
